		if external && !s.externalMemberDone(raw) {
			return false
		}
		if !external {
			slug = strings.TrimPrefix(slug, "spec:")
			if !terminalStatuses[statuses[slug]] {
				return false
			}
			member = member || slug == spec
		}
	}
	return member && len(milestone.Specs) > 0
}

