// ScopedDeliveryProvenanceDigest binds evidence only to the claims and change
// sets consumed by one spec. Adding an unrelated target or change set cannot
// invalidate historical evidence for this scope.
func ScopedDeliveryProvenanceDigest(graph DeliveryIntegrityGraph, spec string) string {
	claims := []ArtifactClaim{}
	sets := []ChangeSet{}
	for _, claim := range graph.Claims {
		if claim.Spec == spec {
			claims = append(claims, claim)
		}
	}
	for _, set := range graph.ChangeSets {
		if set.Spec == spec {
			sets = append(sets, set)
		}
	}
	sort.Slice(claims, func(i, j int) bool { return claimKey(claims[i]) < claimKey(claims[j]) })
	sort.Slice(sets, func(i, j int) bool { return sets[i].ID < sets[j].ID })
	raw, _ := json.Marshal(struct {
		Claims []ArtifactClaim `json:"claims"`
		Sets   []ChangeSet     `json:"change_sets"`
	}{claims, withoutMaterialDigest(sets)})
	sum := sha256.Sum256(raw)
	return "sha256:" + hex.EncodeToString(sum[:])
}

func deliveryEvidenceCurrent(result DeliveryValidationResult, spec, status string, graph DeliveryIntegrityGraph, sets []ChangeSet) bool {
	if bound := result.MaterialProvenance[spec]; bound != "" {
		// A material binding governs: a mismatch is stale, never a fall-through
		// to the commit-bound rules below. Only a closed spec keeps its exemption.
		if bound == ScopedMaterialDigest(graph, spec) {
			return true
		}
		return status == "done" && result.GeneratedAt != ""
	}
	if scoped := result.ScopeProvenance[spec]; scoped != "" {
		if scoped == ScopedDeliveryProvenanceDigest(graph, spec) {
			return true
		}
		if status == "done" && result.GeneratedAt != "" {
			return true
		}
		return false
	}
	if result.ProvenanceDigest != "" && result.ProvenanceDigest == graph.ProvenanceDigest {
		return true
	}
	// Results emitted before scope_provenance existed were module-wide. Preserve
	// them only for already-closed historical specs: their immutable closeout
	// cannot retroactively acquire the new field, and unrelated later targets
	// must not invalidate them. Open/current scopes never receive this bridge.
	if status == "done" && result.ProvenanceDigest != "" && result.GeneratedAt != "" {
		return true
	}
	if result.GitHead == "" {
		return false
	}
	for _, set := range sets {
		if result.GitHead == set.Head || result.GitHead == set.ResolvedHead {
			return true
		}
		for _, commit := range set.Commits {
			if result.GitHead == commit {
				return true
			}
		}
	}
	return false
}

func finalizeExtendedDeliveryGraph(graph *DeliveryIntegrityGraph) {
	sort.Slice(graph.Nodes, func(i, j int) bool { return graph.Nodes[i].ID < graph.Nodes[j].ID })
	sort.Slice(graph.Edges, func(i, j int) bool { return edgeLess(graph.Edges[i], graph.Edges[j]) })
	graph.Edges = dedupeSortedEdges(graph.Edges)
	sort.Slice(graph.Findings, func(i, j int) bool { return graph.Findings[i].ID < graph.Findings[j].ID })
	sort.Slice(graph.Deliveries, func(i, j int) bool { return graph.Deliveries[i].Ref < graph.Deliveries[j].Ref })
	sort.Slice(graph.ValidationResults, func(i, j int) bool { return graph.ValidationResults[i].ID < graph.ValidationResults[j].ID })
	sort.Slice(graph.RoadmapCriteria, func(i, j int) bool {

		return out, nil
	})
}

// milestoneReachedObligations projects the milestones that can be closed. The
// rule restricts nothing: a reached milestone waits for an operator to close it,
// and the roadmap's own close refuses it anyway. What cannot be read leaves the
// producer's coverage incomplete and never reads as reached.
func (s Store) milestoneReachedObligations(project, scope string, coverage *Coverage) ([]Obligation, error) {
	lost := func(err error) ([]Obligation, error) {
		markCoverageIncomplete(coverage, "reached milestones could not be read: "+err.Error())
		return nil, nil
	}
	spec, within := "", scope
	if ref, err := ParseScopeRef(scope); scope != "" && err == nil && ref.Kind == "spec" {
		spec, within = ref.Slug, ""
	}
	candidates, err := s.milestonesWithTerminalMembers(spec, within)
	if err != nil {
		return lost(err)
	}
	recorded, refused, err := s.milestonesWithRecordedApproval(append(candidates, s.soleMemberRefs(candidates)...))
	if err != nil {
		return lost(err)
	}
	policy, _, err := s.loadReviewPolicy()
	if err != nil {
		return lost(err)
	}
	var out []Obligation
	for _, ref := range candidates {
		parsed, err := ParseScopeRef(ref)
		if err != nil {
			return nil, err
		}
		required, err := s.reviewRequiredForScope(parsed, policy)
		if err != nil {
			return lost(err)
		}
		if policy.CloseoutReviewAdopted() {
			// Under an adopted closeout review policy a reached milestone is
			// closed only by its explicit close, which publishes a receipt,
			// approved review or not (spec pose-closeout-review-policy-by-cost-benefit).
			closed, err := s.closedByReceipt(ref)
			if err != nil {
				return lost(err)
			}
			if closed {
				continue
			}
		} else {
			member, sole := s.soleMemberOf(parsed)
			owed := !recorded[ref] && !(sole && recorded["spec:"+member]) && s.declaredUnreviewed(parsed) == ""
			if !required || !owed && !refused[ref] {
				continue
			}
		}
		source := QualifyNodeRef(project, ArtifactRef{Kind: "milestone", Slug: parsed.Roadmap, Milestone: parsed.Milestone}, "", "")
		o := newObligation(project, "closeout", source, "milestone-reached", ref)
		o.Category = ObligationReconciliation
		o.ReasonCode = "milestone-reached"
		o.Condition = DiagnosticCatalog["milestone-reached"].Condition
		o.Effects = []ObligationEffect{{Phase: PhaseCloseout, Mode: EffectAdvisory}}
		o.Waiting = WaitingActor
		o.Message = ref + " is reached: pose close " + ref
		out = append(out, o)
	}

